class Produk {
  constructor(
    public readonly kode: string,
    public nama: string,
    private harga: number,
  ) {}
  naikkanHarga(persen: number): void {
    this.harga = Math.round(this.harga * (1 + persen / 100));
  }
  info(): string {
    return `${this.kode} ${this.nama} ${this.harga}`;
  }
}
const p = new Produk("P01", "Kopi", 18000);
p.nama = "Kopi Susu";
p.naikkanHarga(10);
console.log(p.info());

