class Rekening {
  private saldo = 0;
  constructor(public readonly nomor: string, public pemilik: string) {}
  setor(jumlah: number): void {
    this.saldo += jumlah;
  }
  info(): string {
    return `${this.nomor} ${this.pemilik} ${this.saldo}`;
  }
}
const r = new Rekening("001", "Rina");
r.setor(50000);
console.log(r.info());

