cards.solution:
class Menu {
  constructor(public readonly kode: string, public nama: string, private harga: number) {}
  label(): string {
    return `${this.kode}-${this.nama}-${this.harga}`;
  }
}
console.log(new Menu("M1", "Nasi Goreng", 25000).label());
